52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /** Dedicated audit logger; each successful owner create emits one line here. */
68	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        Map<String, Integer> householdSizes = householdSizes();
101	        List<OwnerDto> ownerDtos = new java.util.ArrayList<>();
102	        for (Owner owner : owners) {
103	            OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
104	            applyMembership(ownerDto, owner, householdSizes);
105	            ownerDtos.add(ownerDto);
106	        }
107	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
113	        Owner owner = this.clinicService.findOwnerById(ownerId);
114	        if (owner == null) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
118	        applyMembership(ownerDto, owner);
119	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
120	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
126	        HttpHeaders headers = new HttpHeaders();
127	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
128	        String address = applyAddress(owner, ownerFieldsDto);
129	        if (address.isEmpty()) {
130	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	        }
132	        owner.setAddress(address);
133	        String telephone = toE164(owner.getTelephone());
134	        if (telephone == null) {
135	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
136	        }
137	        owner.setTelephone(telephone);
138	        if (owner.getEmail() != null) {
139	            String email = normalizeEmail(owner.getEmail());
140	            if (email == null) {
141	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
142	            }
143	            owner.setEmail(email);
144	        }
145	        if (owner.getPostcode() != null && !isValidPostcode(owner.getPostcode(), owner.getCity())) {
146	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
147	        }
148	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
149	        if (effectiveRegistrationDate == null) {
150	            effectiveRegistrationDate = LocalDate.now();
151	        }
152	        else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
153	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
154	        }
155	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
156	        owner.setRegistrationDate(registrationDate);
157	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
158	            return new ResponseEntity<>(HttpStatus.CONFLICT);
159	        }
160	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
161	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
162	        }
163	        // The householdId is deterministic: the first twelve hex characters of SHA-256 over
164	        // '<normalizedLastName>|<postcode>'. Owners sharing a last name and postcode therefore
165	        // share the household automatically. An owner without a postcode has no household.
166	        boolean declaredHouseholdMember = false;
167	        if (owner.getPostcode() != null) {
168	            String householdId = householdId(householdKey(owner.getLastName()), owner.getPostcode());
169	            owner.setHouseholdId(householdId);
170	            // Because the household is now keyed on (lastName, postcode), a second owner in the
171	            // same household is a household duplicate: rejected with 409 unless it opts in with
172	            // 'sharesHousehold', in which case it is created as a declared household member.
173	            boolean householdOccupied = false;
174	            for (Owner existing : this.clinicService.findAllOwners()) {
175	                if (existing.isDeleted()) {
176	                    continue;
177	                }
178	                if (householdId.equals(computeHouseholdId(existing))) {
179	                    householdOccupied = true;
180	                    break;
181	                }
182	            }
183	            if (householdOccupied) {
184	                if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
185	                    return new ResponseEntity<>(HttpStatus.CONFLICT);
186	                }
187	                declaredHouseholdMember = true;
188	            }
189	        }
190	        // Consolidated duplicate detection: reject only when the whole identityKey
191	        // (normalized telephone | email | householdId) matches an existing owner's.
192	        String identityKey = identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
193	        for (Owner existing : this.clinicService.findAllOwners()) {
194	            if (existing.isDeleted()) {
195	                continue;
196	            }
197	            if (identityKey.equals(identityKey(toE164(existing.getTelephone()),
198	                emailForKey(existing.getEmail()), existing.getHouseholdId()))) {
199	                return new ResponseEntity<>(HttpStatus.CONFLICT);
200	            }
201	        }
202	        // Soft-match: the owner is not a hard (identityKey) duplicate, but if it shares an
203	        // existing owner's last name and postcode while having a different normalized
204	        // telephone it is still created and flagged as a possible duplicate of that owner. A
205	        // declared household member, however, is not a suspected duplicate, so it is never flagged.
206	        if (declaredHouseholdMember) {
207	            owner.setPossibleDuplicate(false);
208	        }
209	        else {
210	            applyPossibleDuplicate(owner);
211	        }
212	        owner.setCustomerCode(deduplicatedCustomerCode(
213	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName())));
214	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
215	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
216	        this.clinicService.saveOwner(owner);
217	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
218	        applyMembership(ownerDto, owner);
219	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
220	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
221	            ownerDto.getMembershipLevel(), owner.getMembershipNumber());
222	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
223	        headers.setLocation(UriComponentsBuilder.newInstance()
224	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
225	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
226	    }
