417	    /**
418	     * Builds the customer code for a newly created owner, formatted
419	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the canonical region
420	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
421	     * {@code "UNKNOWN"} when the postcode resolves no region) and {@code HASH8} is the
422	     * first eight upper-case hex characters of the SHA-256 digest of
423	     * {@code normalizedTelephone + lastName}. The code carries no sequence number, so it is
424	     * stable for a given telephone and last name rather than dependent on creation order.
425	     *
426	     * @param postcode            the owner's postcode (may be {@code null})
427	     * @param normalizedTelephone the owner's normalized E.164 telephone
428	     * @param lastName            the owner's last name
429	     * @return the assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
430	     */
431	    private static String customerCode(String postcode, String normalizedTelephone, String lastName) {
432	        String region = org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
433	        return region + "-" + sha256Hex8(normalizedTelephone + lastName);
434	    }
435	
436	    /**
437	     * De-duplicates a freshly computed {@code base} customer code against the codes already
438	     * assigned to existing owners. When {@code base} is free it is returned unchanged;
439	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of two or more that
440	     * yields a code no existing owner holds.
441	     *
442	     * @param base the computed {@code '<REGION>-<HASH8>'} customer code
443	     * @return {@code base}, or {@code base + "-<n>"} de-duplicated to be unique
444	     */
445	    private String deduplicatedCustomerCode(String base) {
446	        Set<String> existing = new HashSet<>();
447	        for (Owner owner : this.clinicService.findAllOwners()) {
448	            if (owner.getCustomerCode() != null) {
449	                existing.add(owner.getCustomerCode());
450	            }
451	        }
452	        if (!existing.contains(base)) {
453	            return base;
454	        }
455	        int n = 2;
456	        while (existing.contains(base + "-" + n)) {
457	            n++;
458	        }
459	        return base + "-" + n;
460	    }
461	
462	    /**
463	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
464	     * bytes of {@code source} — the {@code HASH8} component of an owner's customer code.
465	     *
466	     * @param source the string to hash
467	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
468	     */
469	    private static String sha256Hex8(String source) {
470	        try {
471	            byte[] digest = MessageDigest.getInstance("SHA-256")
472	                .digest(source.getBytes(StandardCharsets.UTF_8));
473	            StringBuilder hex = new StringBuilder(digest.length * 2);
474	            for (byte b : digest) {
475	                hex.append(String.format("%02x", b));
476	            }
477	            return hex.substring(0, 8).toUpperCase();
478	        } catch (NoSuchAlgorithmException e) {
479	            throw new IllegalStateException("SHA-256 not available", e);
480	        }
481	    }
