483	    /**
484	     * Builds the membership number for a newly created owner, formatted
485	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
486	     * customer code and {@code YY} is the last two digits of the owner's registration
487	     * date year, zero-padded to two digits.
488	     *
489	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
490	     * @param registrationDate the owner's registration date
491	     * @return the assigned membership number (e.g. {@code 'NSW-1A2B3C4D-M26'})
492	     */
493	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
494	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
495	    }
