517	    /**
518	     * Canonical expansions applied to common street-type abbreviations during address
519	     * normalization. Keys and values are upper-cased so the lookup runs after the address
520	     * has itself been upper-cased.
521	     */
522	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
523	        "ST", "STREET",
524	        "RD", "ROAD",
525	        "AVE", "AVENUE");
526	
527	    /**
528	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
529	     * every run of internal whitespace is collapsed to a single space, the result is
530	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
531	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
532	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
533	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
534	     * returned and compared for household duplicates; an address that is blank once
535	     * normalized fails the required-field check.
536	     *
537	     * @param address the raw address value supplied by the client
538	     * @return the normalized address (empty string when {@code address} is null or blank)
539	     */
540	    /**
541	     * Normalizes the address an owner supplies, preferring the structured form, and stores the
542	     * normalized structured lines on the owner. When a non-blank {@code addressLine1} is present
543	     * the structured fields are used: {@code addressLine1} (and {@code addressLine2}, when
544	     * present) are {@link #normalizeAddress normalized} and set on the owner, and the composed
545	     * address returned is the normalized {@code addressLine1} with a single space and the
546	     * normalized {@code addressLine2} appended when {@code addressLine2} is present. Otherwise
547	     * the flat {@code address} is normalized and returned, and the structured lines are left
548	     * unset. The returned value becomes the owner's stored {@code address}, read by everything
549	     * downstream (household hash, postcode validation and locality); an owner that supplies
550	     * neither form yields an empty string, failing the required-address check.
551	     *
552	     * @param owner          the owner being created, whose structured address lines are set here
553	     * @param ownerFieldsDto the submitted owner fields
554	     * @return the composed, normalized address (empty string when no address form is supplied)
555	     */
556	    private static String applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
557	        String addressLine1 = ownerFieldsDto.getAddressLine1();
558	        if (addressLine1 != null && !addressLine1.isBlank()) {
559	            String normalizedLine1 = normalizeAddress(addressLine1);
560	            owner.setAddressLine1(normalizedLine1);
561	            String addressLine2 = ownerFieldsDto.getAddressLine2();
562	            if (addressLine2 != null && !addressLine2.isBlank()) {
563	                String normalizedLine2 = normalizeAddress(addressLine2);
564	                owner.setAddressLine2(normalizedLine2);
565	                return normalizedLine1 + " " + normalizedLine2;
566	            }
567	            owner.setAddressLine2(null);
568	            return normalizedLine1;
569	        }
570	        owner.setAddressLine1(null);
571	        owner.setAddressLine2(null);
572	        return normalizeAddress(ownerFieldsDto.getAddress());
573	    }
574	
575	    private static String normalizeAddress(String address) {
576	        if (address == null) {
577	            return "";
578	        }
579	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
580	        if (collapsed.isEmpty()) {
581	            return "";
582	        }
583	        StringBuilder normalized = new StringBuilder(collapsed.length());
584	        for (String token : collapsed.split(" ")) {
585	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
586	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
587	            if (normalized.length() > 0) {
588	                normalized.append(' ');
589	            }
590	            normalized.append(expanded != null ? expanded : token);
591	        }
592	        return normalized.toString();
593	    }
594	
595	    /**
596	     * Normalizes a last name or address for household-duplicate comparison: leading and
597	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
598	     * single space and the result is lower-cased. Two owners are considered to share a
599	     * household when both their last names and addresses produce the same key.
600	     *
601	     * @param value the raw last name or address value
602	     * @return the normalized comparison key (empty string when {@code value} is null)
603	     */
604	    private static String householdKey(String value) {
605	        if (value == null) {
606	            return "";
607	        }
608	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
609	    }
610	
611	    /**
612	     * Derives the stable shared household identifier for the given normalized last name key
613	     * and postcode. The identifier is deterministic — the same household (same
614	     * {@link #householdKey normalized} last name and postcode) always maps to the same
615	     * value — so every owner in a household is assigned an identical id. It is the
616	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
617	     * '<lastNameKey>|<postcode>'}.
618	     *
619	     * @param lastNameKey the normalized last name key
620	     * @param postcode    the owner's postcode
621	     * @return the shared household identifier
622	     */
623	    private static String householdId(String lastNameKey, String postcode) {
624	        String source = lastNameKey + "|" + postcode;
625	        try {
626	            byte[] digest = MessageDigest.getInstance("SHA-256")
627	                .digest(source.getBytes(StandardCharsets.UTF_8));
628	            StringBuilder hex = new StringBuilder(digest.length * 2);
629	            for (byte b : digest) {
630	                hex.append(String.format("%02x", b));
631	            }
632	            return hex.substring(0, 12).toUpperCase();
633	        } catch (NoSuchAlgorithmException e) {
634	            throw new IllegalStateException("SHA-256 not available", e);
635	        }
636	    }
637	
638	    /**
639	     * Computes the deterministic {@link #householdId household id} an existing owner belongs to,
640	     * derived from its {@link #householdKey normalized} last name and its postcode. Returns
641	     * {@code null} when the owner has no postcode (such an owner has no household), so it never
642	     * collides with a computed household id.
643	     *
644	     * @param owner the existing owner
645	     * @return the owner's household id, or {@code null} when it has no postcode
646	     */
647	    private static String computeHouseholdId(Owner owner) {
648	        if (owner.getPostcode() == null) {
649	            return null;
650	        }
651	        return householdId(householdKey(owner.getLastName()), owner.getPostcode());
652	    }
653	
654	    /**
655	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
656	     * dto, sizing the owner's household from all owners so the household-of-three-or-more
657	     * factor is scored correctly. Use {@link #applyMembership(OwnerDto, Owner, Map)} instead
658	     * when mapping a collection to size every household from a single scan.
659	     *
660	     * @param ownerDto the dto to populate
661	     * @param owner    the owner being mapped
662	     */
663	    private void applyMembership(OwnerDto ownerDto, Owner owner) {
664	        applyMembership(ownerDto, owner, householdSizes());
665	    }
666	
667	    /**
668	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
669	     * dto using a pre-computed map of household id to member count.
670	     *
671	     * @param ownerDto       the dto to populate
672	     * @param owner          the owner being mapped
673	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
674	     */
675	    private void applyMembership(OwnerDto ownerDto, Owner owner, Map<String, Integer> householdSizes) {
676	        int householdSize = owner.getHouseholdId() == null ? 1
677	            : householdSizes.getOrDefault(owner.getHouseholdId(), 1);
678	        int points = MembershipPoints.points(owner, householdSize);
679	        ownerDto.setMembershipPoints(points);
680	        ownerDto.setMembershipLevel(MembershipPoints.level(points));
681	    }
682	
683	    /**
684	     * Counts how many owners belong to each household, keyed by household id. Owners without a
685	     * household id (no postcode) are excluded — such an owner is its own single-member household.
686	     *
687	     * @return a map from household id to the number of owners sharing it
688	     */
689	    private Map<String, Integer> householdSizes() {
690	        Map<String, Integer> sizes = new java.util.HashMap<>();
691	        for (Owner existing : this.clinicService.findAllOwners()) {
692	            String householdId = existing.getHouseholdId();
693	            if (householdId != null) {
694	                sizes.merge(householdId, 1, Integer::sum);
695	            }
696	        }
697	        return sizes;
698	    }
699	
700	    /**
701	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
702	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
703	     * possible duplicate when an existing owner shares its last name (compared
704	     * case-insensitively with collapsed whitespace) and its postcode while having a
705	     * different normalized telephone; {@code possibleDuplicateOf} is then set to that
706	     * existing owner's id. When several existing owners match, the one with the lowest id
707	     * is chosen so the result is deterministic. When no such owner exists — or the new
708	     * owner has no postcode to compare — {@code possibleDuplicate} is set to {@code false}
709	     * and no matching id is recorded.
710	     *
711	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
712	     */
713	    private void applyPossibleDuplicate(Owner owner) {
714	        owner.setPossibleDuplicate(false);
715	        if (owner.getPostcode() == null) {
716	            return;
717	        }
718	        String lastNameKey = householdKey(owner.getLastName());
719	        Owner match = null;
720	        for (Owner existing : this.clinicService.findAllOwners()) {
721	            if (lastNameKey.equals(householdKey(existing.getLastName()))
722	                && owner.getPostcode().equals(existing.getPostcode())
723	                && !owner.getTelephone().equals(toE164(existing.getTelephone()))) {
724	                if (match == null || (existing.getId() != null
725	                    && existing.getId() < match.getId())) {
726	                    match = existing;
727	                }
728	            }
729	        }
730	        if (match != null) {
731	            owner.setPossibleDuplicate(true);
732	            owner.setPossibleDuplicateOf(match.getId());
733	        }
734	    }
735	
736	    /**
737	     * Builds the derived duplicate-detection identity key from an owner's normalized
738	     * telephone, email and household id, formatted {@code
739	     * '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Two owners are
740	     * duplicates only when their whole identity keys are equal; because the telephone is
741	     * part of the key, members of the same household with different telephones produce
742	     * different keys and are both allowed.
743	     *
744	     * @param normalizedTelephone the E.164 telephone (may be {@code null})
745	     * @param email               the normalized (lower-cased) email, or {@code null} when absent
746	     * @param householdId         the shared household id, or {@code null} when the owner is not in a household
747	     * @return the identity key string
748	     */
749	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
750	        return (normalizedTelephone == null ? "" : normalizedTelephone)
751	            + "|" + (email == null ? "" : email)
752	            + "|" + (householdId == null ? "" : householdId);
753	    }
754	
755	    /**
756	     * Normalizes an existing owner's stored email for identity-key comparison: trimmed and
757	     * lower-cased, mirroring {@link #normalizeEmail} without re-validating syntax. Returns
758	     * {@code null} when the owner has no email.
759	     *
760	     * @param email the existing owner's stored email (may be {@code null})
761	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is null
762	     */
763	    private static String emailForKey(String email) {
764	        return email == null ? null : email.trim().toLowerCase();
765	    }
766	
767	    /**
768	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
769	     * and brackets are stripped. When the number already carries a leading {@code '+'}
770	     * and country code these are kept; a number written in national trunk form (a leading
771	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
772	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
773	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
774	     * after the {@code '+'}, and its national-number length must be valid for the detected
775	     * country code (see {@link #hasValidNationalLength}).
776	     *
777	     * @param telephone the raw telephone value supplied by the client
778	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
779	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
780	     */
781	    private static String toE164(String telephone) {
782	        if (telephone == null) {
783	            return null;
784	        }
785	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
786	        String digits;
787	        if (cleaned.startsWith("+")) {
788	            digits = cleaned.substring(1);
789	        } else if (cleaned.startsWith("0")) {
790	            digits = "61" + cleaned.substring(1);
791	        } else {
792	            digits = "1" + cleaned;
793	        }
794	        if (!digits.matches("[0-9]{8,15}")) {
795	            return null;
796	        }
797	        if (!hasValidNationalLength(digits)) {
798	            return null;
799	        }
800	        return "+" + digits;
801	    }
802	
803	    /**
804	     * Validates the national-number length of an E.164 digit string against its country
805	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
806	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
807	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
808	     *
809	     * @param digits the E.164 digits (without the leading {@code '+'})
810	     * @return {@code true} when the national-number length is valid for the country code
811	     */
812	    private static boolean hasValidNationalLength(String digits) {
813	        if (digits.startsWith("61")) {
814	            return digits.length() - 2 == 9;
815	        }
816	        if (digits.startsWith("1")) {
817	            return digits.length() - 1 == 10;
818	        }
819	        return true;
820	    }
821	
822	    /**
823	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
824	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
825	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
826	     */
827	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
828	        "NSW", new int[] {2000, 2099},
829	        "VIC", new int[] {3000, 3099},
830	        "QLD", new int[] {4000, 4099});
831	
832	    /**
833	     * Validates an owner's postcode for creation. A postcode is only ever validated when
834	     * present (an absent postcode is optional and accepted). When present it must be exactly
835	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
836	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
837	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
838	     *
839	     * @param postcode the supplied postcode (never {@code null} here)
840	     * @param city     the owner's city, used to derive the region
841	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
842	     *         (signalling a 400 Bad Request)
843	     */
844	    private static boolean isValidPostcode(String postcode, String city) {
845	        if (!postcode.matches("[0-9]{4}")) {
846	            return false;
847	        }
848	        int[] range = REGION_POSTCODES.get(
849	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
850	        if (range == null) {
851	            return true;
852	        }
853	        int value = Integer.parseInt(postcode);
854	        return value >= range[0] && value <= range[1];
855	    }
856	
857	    /**
858	     * Disposable email domains that are not accepted for owner creation. An owner whose
859	     * email domain (compared case-insensitively) is in this set is rejected with a 400
860	     * Bad Request.
861	     */
862	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
863	        "mailinator.com", "tempmail.com", "guerrillamail.com");
864	
865	    /**
866	     * Normalizes an owner email for creation. A present email must be a syntactically
867	     * valid address whose domain is not on the disposable-domain blocklist ({@link
868	     * #DISPOSABLE_EMAIL_DOMAINS}); the returned value is lower-cased.
869	     *
870	     * @param email the raw email value supplied by the client (never {@code null} here)
871	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
872	     *         address or its domain is a disposable domain (signalling a 400 Bad Request)
873	     */
874	    private static String normalizeEmail(String email) {
875	        String trimmed = email.trim();
876	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
877	            return null;
878	        }
879	        String normalized = trimmed.toLowerCase();
880	        String domain = normalized.substring(normalized.indexOf('@') + 1);
881	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
882	            return null;
883	        }
884	        return normalized;
885	    }
886	}
